insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('vrm-rc-03', 'multiple_choice'::question_type, 'Passage: "The ''paradox of choice'' refers to the observation that, beyond a certain point, offering people more options can decrease rather than increase their satisfaction with the choice they eventually make. One proposed explanation is that more options raise the expectations of finding a ''perfect'' choice, making any actual selection feel comparatively disappointing. Another is that evaluating many options simply requires more cognitive effort, leaving people less confident that they made the right call." Which of the following best describes the ''paradox of choice''?', NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'medium'::assessment_difficulty, 'verbal-reasoning-mastery', '{}'::text[], NULL, true)
