insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('vrm-rc-05', 'multiple_choice'::question_type, 'Passage: "Coral bleaching occurs when corals, stressed by unusually warm water, expel the symbiotic algae living in their tissues. These algae supply the coral with most of its energy and its vivid color, so their loss leaves the coral pale and vulnerable to starvation. Bleaching is not immediately fatal — corals can recover if temperatures drop and algae recolonize in time — but repeated or prolonged bleaching events sharply increase coral mortality." Based on the passage, coral bleaching is best described as:', NULL, '[]'::jsonb, NULL, '[]'::jsonb, 'medium'::assessment_difficulty, 'verbal-reasoning-mastery', '{}'::text[], NULL, true)
