insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('read-1a', 'multiple_choice'::question_type, 'Economists studying hiring practices have long noted that employers, unable to directly observe a candidate''s ability before hiring, often rely on costly, visible signals — an elite degree, a demanding internship, a professional certification — as proxies for underlying competence. The signal is valuable to employers precisely because it is expensive for low-ability candidates to fake: only genuinely capable candidates can obtain it at reasonable cost. Critics of this signaling model argue that it wastes resources on credentials that teach little of direct value to the job itself, functioning as a filter rather than as preparation.
insert into question_options (question_id, label, value, image_url, is_correct, "order", score_config) values
  ((select id from questions where external_key = 'read-1a'), 'To explain why costly credentials function as signals of ability and to note a criticism of that function.', '0', NULL, true, 0, '[{"dimensionKey":"verbal","points":1},{"dimensionKey":"reading","points":1}]'::jsonb),
  ((select id from questions where external_key = 'read-1a'), 'To argue that elite degrees should be abolished as hiring criteria.', '1', NULL, false, 1, '[{"dimensionKey":"verbal","points":0}]'::jsonb),
  ((select id from questions where external_key = 'read-1a'), 'To prove that internships teach no job-relevant skills.', '2', NULL, false, 2, '[{"dimensionKey":"verbal","points":0}]'::jsonb),
  ((select id from questions where external_key = 'read-1a'), 'To compare hiring practices across different industries.', '3', NULL, false, 3, '[{"dimensionKey":"verbal","points":0}]'::jsonb);
