insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('read-2a', 'multiple_choice'::question_type, 'In clinical trials, patients who merely believe they are receiving an active treatment often show measurable improvement, a phenomenon researchers attribute partly to expectation itself rather than to any pharmacological effect. This placebo response complicates the evaluation of new drugs: a treatment that outperforms no intervention at all may still fail to outperform a placebo, revealing that its apparent benefit was largely psychological. Well-designed trials therefore compare new treatments against a placebo rather than against nothing, isolating the drug''s effect from the effect of mere expectation.
