  ((select id from questions where external_key = 'read-2a'), 'Comparing a treatment only against no intervention can overstate its true effect, so placebo-controlled comparison is necessary.', '1', NULL, true, 1, '[{"dimensionKey":"verbal","points":1},{"dimensionKey":"reading","points":1}]'::jsonb),
