  ((select id from questions where external_key = 'read-2b'), 'A large study found that outcomes in placebo groups were statistically indistinguishable from outcomes in untreated groups.', '3', NULL, true, 3, '[{"dimensionKey":"verbal","points":1},{"dimensionKey":"reading","points":1}]'::jsonb);
insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('read-3a', 'multiple_choice'::question_type, 'Textualist judges maintain that a statute means what its enacted language would have conveyed to an ordinary reader at the time of passage, regardless of what individual legislators privately intended. Purposivist judges, by contrast, read ambiguous provisions in light of the broader problem Congress evidently sought to solve, even when the literal text admits a narrower reading. Neither camp claims that legislative intent is irrelevant; they disagree chiefly about where that intent is properly located — in the public meaning of the words enacted, or in the evident purpose behind them.
insert into question_options (question_id, label, value, image_url, is_correct, "order", score_config) values
  ((select id from questions where external_key = 'read-3a'), 'Dismissive of purposivism as unworkable.', '0', NULL, false, 0, '[{"dimensionKey":"verbal","points":0}]'::jsonb),
  ((select id from questions where external_key = 'read-3a'), 'Even-handed, presenting each position''s reasoning without endorsing either.', '1', NULL, true, 1, '[{"dimensionKey":"verbal","points":1},{"dimensionKey":"reading","points":1}]'::jsonb),
  ((select id from questions where external_key = 'read-3a'), 'Strongly critical of textualism as overly rigid.', '2', NULL, false, 2, '[{"dimensionKey":"verbal","points":0}]'::jsonb),
  ((select id from questions where external_key = 'read-3a'), 'Openly mocking of both schools of thought.', '3', NULL, false, 3, '[{"dimensionKey":"verbal","points":0}]'::jsonb);
