  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Digit Span Forward', 'Listen to a spoken digit sequence, then recall it in the same order.', 'Each round plays once. Tap the digits back in the order you heard them.', NULL, false, 0.35, 1);
  insert into assessment_sections (assessment_version_id, name, description, instructions, time_limit_seconds, randomize_questions, weight, "order") values (v_ver, 'Digit Span Backward', 'Listen to a spoken digit sequence, then recall it in reverse order.', 'Each round plays once. Tap the digits back in the REVERSE of the order you heard them — this is harder than it sounds.', NULL, false, 0.35, 2);
