  insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('career-aptitude-profile', 'Career Aptitude Profile', 'Maps your Brain Profile strengths and interests against career directions likely to suit how you think.', 'Career Aptitude Profile is built on Holland''s RIASEC model — the theoretical basis for the U.S. Department of Labor''s O*NET Interest Profiler and one of the most widely used frameworks in career counseling. It measures interest across six vocational types: Realistic, Investigative, Artistic, Social, Enterprising, and Conventional. Your highest-scoring types (your "Holland code") point toward career directions that tend to fit how you like to work.', 'compass', v_cat, 'hybrid'::assessment_engine_type, 'easy'::assessment_difficulty, 15, 30, false, 'premium'::assessment_access, 'published'::assessment_status)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'engagement', 'Interest Engagement', 'Overall engagement across all six RIASEC types — how strongly you responded across the board, not which type dominates.', false, NULL, 1)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'realistic', 'Realistic', 'Interest in hands-on, mechanical, physical work.', false, NULL, 2)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'investigative', 'Investigative', 'Interest in analytical, scientific, research-oriented work.', false, NULL, 3)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'artistic', 'Artistic', 'Interest in creative, expressive, design-driven work.', false, NULL, 4)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'social', 'Social', 'Interest in helping, teaching, supporting roles.', false, NULL, 5)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'enterprising', 'Enterprising', 'Interest in leading, persuading, business-oriented work.', false, NULL, 6)
  insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values (v_ass, 'conventional', 'Conventional', 'Interest in organized, detail-oriented, structured work.', false, NULL, 7)
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 0, 30, 'Undifferentiated Profile', 'Your interest ratings were fairly flat across all six types — none stood out strongly. That''s not a bad result; it can mean genuinely broad interests, or that none of these six categories captures what motivates you. Check the six scores above for your closest lean.', ARRAY['Look at your two or three highest-scoring types above, even if none feels dominant — that pairing is still informative', 'Try activities from your highest type or two to see if engagement follows', 'Retake this after trying a few different kinds of work or projects']::text[], NULL, 1);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 31, 50, 'Mildly Differentiated', 'A modest lean toward one or two RIASEC types. Look at your highest-scoring dimensions above for your closest career direction.', ARRAY['Explore roles that combine your top one or two types', 'Notice which specific items you rated highest — the activity itself may matter more than the category']::text[], NULL, 2);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 51, 70, 'Differentiated Profile', 'A clear lean toward specific RIASEC types is visible above. Your highest-scoring one or two types form your Holland code.', ARRAY['Research career paths associated with your top two types (e.g. Investigative + Artistic often points toward research or design-adjacent fields)', 'Weigh your Holland code alongside your Brain Profile''s cognitive strengths for a fuller picture']::text[], NULL, 3);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 71, 85, 'Strongly Differentiated', 'Your interests are clearly concentrated in a small set of RIASEC types — a strong, well-defined Holland code.', ARRAY['A strongly differentiated profile like yours tends to predict clearer career satisfaction in matching fields', 'Seek out roles or projects that lean heavily into your top type specifically, not just adjacent ones']::text[], NULL, 4);
  insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values (v_ass, 'overall', 86, 100, 'Highly Concentrated Profile', 'A very sharply defined interest profile — your top type (or two) stands well above the rest.', ARRAY['This level of clarity is a strong signal — prioritize roles squarely in your top type over ones that only partially fit', 'Consider whether your current path actually uses your top type, or whether it''s worth a deliberate shift']::text[], NULL, 5);
